/// <summary>
///    AVA <c>canGoBatch</c> method.
/// </summary>
/// <returns>
///    <c>boolean</c> as return value
/// </returns>
public boolean canGoBatch()
{
    return false;
}

/// <summary>
///    AVA <c>dialog</c> method.
/// </summary>
/// <returns>
///    <c>Object</c> as return value
/// </returns>
public Object dialog()
{
    DialogRunbase   dialog;
    DialogGroup     dialogGroup;

    dialog = super();

    dialogGroup     = dialog.addGroup();
    dialogGroup.caption("@NDX:NXABuildingProjectStatus");
    dialogKBVStatus = dialog.addFieldValue(enumStr(KCS_KBVStatus), kcs_KBVStatus);
    dialogReasonId  = dialog.addFieldValue(extendedtypestr(SmmQuotationReasonId), smmQuotationReasonId);

    return dialog;
}

/// <summary>
///    AVA <c>getFromDialog</c> method.
/// </summary>
/// <returns>
///    <c>boolean</c> as return value
/// </returns>
public boolean getFromDialog()
{
    boolean ret;

    ret = super();

    kcs_KBVStatus           = dialogKBVStatus.value();
    SmmQuotationReasonId    = dialogReasonId.value();

    return ret;
}

/// <summary>
///    AVA <c>new</c> method.
/// </summary>
protected void new ()
{
    super();
}

/// <summary>
///    AVA <c>pack</c> method.
/// </summary>
/// <returns>
///    <c>container</c> as return value
/// </returns>
public container pack()
{
    return [#CurrentVersion,#CurrentList];
}

/// <summary>
///    AVA <c>parmKCS_KBVBuildingProjectId</c> method.
/// </summary>
/// <param name="_kcs_KBVBuildingProjectId">
///    <c>KCS_KBVBuildingProjectId</c> as type
/// </param>
/// <returns>
///    <c>KCS_KBVBuildingProjectId</c> as return value
/// </returns>
public KCS_KBVBuildingProjectId parmKCS_KBVBuildingProjectId(KCS_KBVBuildingProjectId _kcs_KBVBuildingProjectId = kcs_KBVBuildingProjectId)
{
    kcs_KBVBuildingProjectId = _kcs_KBVBuildingProjectId;

    return kcs_KBVBuildingProjectId;
}

/// <summary>
///    AVA <c>run</c> method.
/// </summary>
void run()
{
    KCS_KBVBuildingProjectTable myKCS_KBVBuildingProjectTable;
    CompanyInfo locCompanyInfo;

    myKCS_KBVBuildingProjectTable   = KCS_KBVBuildingProjectTable::find(this.parmKCS_KBVBuildingProjectId());
    locCompanyInfo                  = CompanyInfo::find();

    if (myKCS_KBVBuildingProjectTable.RecId)
    {
        myKCS_KBVBuildingProjectTable.selectForUpdate(true);
        myKCS_KBVBuildingProjectTable.smmQuotationReasonId      = smmQuotationReasonId;
        myKCS_KBVBuildingProjectTable.KCS_KBVStatus             = kcs_KBVStatus;

        if(     myKCS_KBVBuildingProjectTable.KCS_KBVStatus == KCS_KBVStatus::Declined
            ||  myKCS_KBVBuildingProjectTable.KCS_KBVStatus == KCS_KBVStatus::Lost
            ||  myKCS_KBVBuildingProjectTable.KCS_KBVStatus == KCS_KBVStatus::Won  )
        {
            myKCS_KBVBuildingProjectTable.KCS_KBVClosedBy            = HcmWorkerLookup::currentWorker();
            myKCS_KBVBuildingProjectTable.KCS_KBVClosedDate          = DateTimeUtil::getToday(DateTimeUtil::getUserPreferredTimeZone());
            myKCS_KBVBuildingProjectTable.KCS_KBVClosedInDataAreaID  = locCompanyInfo.DataArea; //curExt();
        }
        else
        {
            myKCS_KBVBuildingProjectTable.KCS_KBVClosedBy            = 0;
            myKCS_KBVBuildingProjectTable.KCS_KBVClosedDate          = dateNull();
            myKCS_KBVBuildingProjectTable.KCS_KBVClosedInDataAreaID  = '';
        }

        if(myKCS_KBVBuildingProjectTable.validateWrite())
        {
            ttsbegin;
            myKCS_KBVBuildingProjectTable.write();
            ttscommit;
        }
    }
}

