/// <summary>
///    AVA <c>unpack</c> method.
/// </summary>
/// <param name="packedClass">
///    <c>container</c> as type
/// </param>
/// <returns>
///    <c>boolean</c> as return value
/// </returns>
public boolean unpack(container packedClass)
{
    Version     version;

    version = RunBase::getVersion(packedClass);

    switch (version)
    {
        case #CurrentVersion:
            [version,#CurrentList] = packedClass;
            break;

        default:
            return false;
    }

    return true;
}

/// <summary>
///    AVA <c>construct</c> method.
/// </summary>
/// <returns>
///    <c>NDX_KBVSetBPStatusMan</c> as return value
/// </returns>
server static NDX_KBVSetBPStatusMan construct()
{
    return new NDX_KBVSetBPStatusMan();
}

/// <summary>
///    AVA <c>main</c> method.
/// </summary>
/// <param name="args">
///    <c>Args</c> as type
/// </param>
static void main(Args args)
{
    Common                      record      = args.record();
    KCS_KBVBuildingProjectTable kcs_KBVBuildingProjectTable;
    NDX_KBVSetBPStatusMan       nDX_KBVSetBPStatusMan;
    FormDataSource              locFormDataSource;
    int                         locDSPos;

    if (!args)
    {
        throw error("@SYS25407");
    }

    if (!record.TableId == tablenum(KCS_KBVBUildingProjectTable))
    {
        throw error("@NDX:NXAPassedWrongRecord");
    }
    else
    {
        kcs_KBVBuildingProjectTable = record;

        nDX_KBVSetBPStatusMan       = NDX_KBVSetBPStatusMan::construct();

        nDX_KBVSetBPStatusMan.parmkcs_KBVBuildingProjectId(kcs_KBVBuildingProjectTable.KCS_KBVBuildingProjectID);

        if (nDX_KBVSetBPStatusMan.prompt())
        {
            //nDX_KBVSetBPStatusMan.run();    // BP: replaced with runOperation()
            nDX_KBVSetBPStatusMan.runOperation();

            if (kcs_KBVBuildingProjectTable)
            {                    
                /* KCS_KBVClosedBy relation to worker was not refreshed with this implementation
                kcs_KBVBuildingProjectTable.dataSource().reread();
                kcs_KBVBuildingProjectTable.dataSource().refresh();
                */
                //int pos = kcs_KBVBuildingProjectTable.dataSource().getPosition();   // BP: replaced by FormDataUtil::getFormDataSource(Common).positionToRecord(Common);
                locFormDataSource   = FormDataUtil::getFormDataSource(record);
                locDSPos            = locFormDataSource.positionToRecord(record);
                locFormDataSource.research(); //true);
                locFormDataSource.setPosition(locDSPos);
            }
        }
    }
}

